const PORTION = 10; // Kanäle je Portion (talents_abruf_liste p_anzahl)
// Lauf starten (Stefan 18.10.2026): Portionen der fälligen Kanäle nacheinander abarbeiten (talents_abruf_liste mit p_anzahl).
// erledigt = in diesem Lauf schon bearbeitete Kanäle (auch mit Fehler), damit sie nicht erneut drankommen.
// Sofortabruf (Stefan 19.10.2026): Aufruf aus ALLY 16 über "Sofort (Einladung)" mit kanal_id und erstabruf -> nur dieser Kanal
// (Liste mit Kanal-Filter, Migration 52; erstabruf = bis 30 Tage zurück). Der nächtliche Lauf bleibt unverändert.
const sofort = $('Sofort (Einladung)').isExecuted ? ($('Sofort (Einladung)').first().json || {}) : null;
if (sofort) {
  const kanal_id = Number(sofort.kanal_id);
  if (!(Number.isInteger(kanal_id) && kanal_id > 0)) return [];
  // Migration 194 (Stefan 01.11.2026, „Daten jetzt abrufen“): alle_beitraege nur vom Knopf im Talent-Profil (ALLY 20); ALLY 16 schickt es nicht (= false)
  return [{ json: { runde: 0, erledigt: [], anzahl: PORTION, kanal_id, erstabruf: sofort.erstabruf === true, alle_beitraege: sofort.alle_beitraege === true } }];
}
return [{ json: { runde: 0, erledigt: [], anzahl: PORTION } }];

const ART = 'taeglich';
// Kanäle vorbereiten (Stefan 18.10.2026): fällige Kanäle aus talents_abruf_liste OHNE Zugangsschlüssel weitergeben.
// Die Schlüssel liest nur "Graph-Abruf" (Kopfzeile Authorization) direkt aus "Liste holen".
// Je Eintrag der Liste ein Account (Stefan 18.10.2026, Vertrag Migration 45, 4.1): Host und Anmeldeweg kommen aus talents_abruf_liste.
// Anmeldung über Facebook: graph.facebook.com, Seiten- und Nutzer-Schlüssel (Verhalten wie bisher).
// Anmeldung über Instagram: graph.instagram.com, nur der Nutzer-Schlüssel, als Parameter access_token (wie in der Meta-Doku, keine Kopfzeile).
// Die Medienfelder caption und media_product_type
// gibt es dort laut Meta-Doku nicht; "Graph-Abruf" (TALENTS 1) lässt sie in der Adresse weg. Storys (TALENTS 2) nur über Facebook.
// Fehlen host/anmeldeweg (Liste vor Migration 45), gilt die Anmeldung über Facebook (Stefan 18.10.2026).
const HOSTS = { facebook: 'graph.facebook.com', instagram: 'graph.instagram.com' };
const r = $input.first().json.r || {};
if (r.ok !== true) throw new Error('Talents-Abruf (' + ART + '): ' + String(r.fehler || 'Die Liste der fälligen Kanäle ist nicht lesbar.').slice(0, 200));
const lauf = $('Portion anfordern').first().json;
const erledigt = new Set((Array.isArray(lauf.erledigt) ? lauf.erledigt : []).map(Number));
const out = [];
for (const k of Array.isArray(r.kanaele) ? r.kanaele : []) {
  const id = Number(k && k.kanal_id);
  if (!(id > 0) || erledigt.has(id)) continue;
  const weg = String(k.anmeldeweg || 'facebook');
  const host = String(k.host || HOSTS.facebook);
  const nurNutzer = weg === 'instagram';
  // Storys gibt es laut Vertrag nur bei der Anmeldung über Facebook; die Liste liefert solche Accounts hier nicht. Kommt doch einer,
  // gilt er als erledigt (übersprungen, ohne Abruf, Speichern und Fehler), damit er keine Portion blockiert (Stefan 18.10.2026)
  if (nurNutzer && ART === 'stuendlich') { out.push({ json: { start: true, kanal_id: id, ueberspringen: true } }); continue; }
  const reihenfolge = (Array.isArray(k.reihenfolge) ? k.reihenfolge : []).filter(v => v === 'nutzer' || (v === 'seite' && !nurNutzer));
  const api = String(k.api || '');
  const j = { start: true, kanal_id: id, ig_id: String(k.ig_id || ''), api, reihenfolge,
    schluessel_fehler: k.schluessel_fehler === true || !reihenfolge.length };
  // Adresse muss zum Host und der Host zum Anmeldeweg passen (Stefan 18.10.2026)
  const hostPasst = HOSTS[weg] === host && api.startsWith('https://' + host + '/');
  if (!/^[0-9]{1,30}$/.test(j.ig_id) || !hostPasst || !/^https:\/\/graph\.(facebook|instagram)\.com\/v[0-9]{1,3}\.[0-9]{1,2}$/.test(api)) j.ungueltig = true;
  if (ART === 'taeglich') {
    j.tag = k.tag; j.since = k.since; j.until = k.until; j.seit_unix = k.seit_unix;
    // Migration 151 (Punkt 2j): Bildadressen laufen bald ab → vollständige Beitragsliste holen
    j.vorschau_auffrischen = k.vorschau_auffrischen === true;
    j.beitraege = (Array.isArray(k.beitraege) ? k.beitraege : []).map(b => ({ extern_id: b.extern_id, art: b.art, produkt_art: b.produkt_art }));
    // Sofortabruf mit Erstabruf (Stefan 19.10.2026): Tage (bis 30) aus talents_abruf_liste_fuer, ohne Schlüssel
    if (k.erstabruf === true && Array.isArray(k.tage)) {
      j.erstabruf = true;
      j.tage = k.tage.filter(t => t && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(t.tag)) && Number(t.since) > 0 && Number(t.until) > Number(t.since))
        .slice(-30).map(t => ({ tag: String(t.tag), since: Number(t.since), until: Number(t.until) }));
    }
  }
  out.push({ json: j });
}
return out;

const PORTION = 10; // Kanäle je Portion (talents_abruf_liste p_anzahl)
// Nächste Portion? (Stefan 18.10.2026): weiter, solange talents_abruf_liste weitere fällige Kanäle meldet.
// Migration 195 (Stefan 01.11.2026, Abrufzeiten): die Liste vermerkt im Zeitplan-Lauf jeden ausgegebenen Kanal als Versuch (talent_abruf_versuche);
// bearbeitete Kanäle (auch mit Fehler) stehen danach nicht mehr in der Liste, die nächste Portion ist wieder PORTION groß. erledigt bleibt als Schutz.
// Ende bei App-Grenze (stopp_alle), ohne weitere Kanäle oder nach MAX_RUNDEN Portionen.
const MAX_RUNDEN = 30;
const r = $('Liste holen').first().json.r || {};
const lauf = $('Portion anfordern').first().json;
const fertig = $input.all().map(i => i.json || {});
const erledigt = Array.from(new Set((Array.isArray(lauf.erledigt) ? lauf.erledigt : []).concat(fertig.map(e => Number(e.kanal_id))).map(Number).filter(n => n > 0)));
if (fertig.some(e => e.stopp_alle === true)) return [];
if (!(Number(r.weitere) > 0)) return [];
const runde = (Number(lauf.runde) || 0) + 1;
if (runde >= MAX_RUNDEN) return [];
return [{ json: { runde, erledigt, anzahl: PORTION } }];

// Abruf steuern – TALENTS 1, täglicher Abruf (Stefan 18.10.2026), Kennzahlen laut meta_recherche.md (nur gültige, keine veralteten):
// 1. Konto-Insights des Vortags (period=day, metric_type=total_value, since/until aus talents_abruf_liste) – zugleich Test der Schlüssel-Variante
// 2. follows_and_unfollows mit breakdown=follow_type (erst ab 100 Followern; Fehler werden übersprungen)
// 3. followers_count, media_count am Konto
// 4. /media seitenweise (seit_unix aus der Liste; erster Abruf: alle Seiten). Unvollständige Liste wird nicht gespeichert.
// 5. Insights je verfolgtem Beitrag (Liste aus der Datenbank) und je neuem Beitrag seit dem letzten Abruf (nicht beim ersten Abruf)
// Sofortabruf mit Erstabruf (Stefan 19.10.2026): 1. und 2. je Tag für die Tage aus der Liste (bis 30 Tage zurück, Meta liefert die
// Konto-Kennzahlen je Tag mit since/until), dazu Insights der Beiträge der letzten 30 Tage (höchstens 100) schon beim ersten Abruf.
const ART = 'taeglich';
const KONTO_A = 'reach,views,accounts_engaged,total_interactions,likes,comments,saves,shares,replies,reposts,profile_links_taps';
const KONTO_B = 'reach,views,accounts_engaged,total_interactions,likes,comments,saves,shares';
const MEDIEN_FELDER_OHNE = 'id,caption,media_type,media_product_type,timestamp,permalink,thumbnail_url,media_url,like_count,comments_count';
// Migration 151 (Punkt 2j): Karussell-Elemente für das Vorschaubild (lehnt die API das Feld ab, Rückfall ohne children)
const MEDIEN_FELDER = MEDIEN_FELDER_OHNE + ',children{media_type,media_url,thumbnail_url}';
const MEDIEN_JE_SEITE = '50';
const MAX_SEITEN = 400;
const ID_MUSTER = /^[A-Za-z0-9_.:-]{1,100}$/;

function insightsKennzahlen(produkt, stufe) {
  const p = String(produkt || '').toUpperCase();
  const basis = 'views,reach,likes,comments,saved,shares,total_interactions';
  if (p === 'STORY') return stufe === 'voll' ? 'views,reach,shares,total_interactions,follows,profile_visits,replies' : 'views,reach,shares,total_interactions';
  if (p === 'REELS') return stufe === 'voll' ? basis + ',ig_reels_avg_watch_time,ig_reels_video_view_total_time' : basis;
  return stufe === 'voll' ? basis + ',follows,profile_visits' : basis;
}
function insightsAnfrage(id, produkt, stufe) {
  return { typ: 'beitrag_insights', pfad: id + '/insights', extern_id: id, produkt: String(produkt || ''), stufe, query: { metric: insightsKennzahlen(produkt, stufe) } };
}
function istBeitragInsights(req) { return req.typ === 'beitrag_insights'; }
function medium(m) {
  if (!m || !ID_MUSTER.test(String(m.id || ''))) return null;
  const w = {};
  if (zahl(m.like_count) !== null) w.like_count = zahl(m.like_count);
  if (zahl(m.comments_count) !== null) w.comments_count = zahl(m.comments_count);
  return { extern_id: String(m.id), art: m.media_type ? String(m.media_type).slice(0, 40) : undefined,
    produkt_art: m.media_product_type ? String(m.media_product_type).slice(0, 40) : undefined,
    erstellt: typeof m.timestamp === 'string' ? m.timestamp : undefined, link: httpsAdresse(m.permalink),
    vorschau_url: vorschauAus(m), text_inhalt: textSauber(m.caption), werte: w };
}
// Vorschaubild (Migration 151, Punkt 2j): nie eine Video-Adresse. Video: thumbnail_url; Bild: media_url; Karussell: erstes Element mit Bild
// (Bild: media_url, Video: thumbnail_url); ohne children nur media_url, wenn es ein Bild ist, sonst nichts.
function vorschauAus(m) {
  const typ = String(m.media_type || '').toUpperCase();
  if (typ === 'VIDEO') return bildAdresse(m.thumbnail_url);
  if (typ === 'CAROUSEL_ALBUM') {
    for (const c of (m.children && Array.isArray(m.children.data) ? m.children.data : [])) {
      const ct = String((c && c.media_type) || '').toUpperCase();
      const u = ct === 'VIDEO' ? bildAdresse(c && c.thumbnail_url) : bildAdresse(c && c.media_url);
      if (u) return u;
    }
    return bildAdresse(m.media_url);
  }
  return bildAdresse(m.thumbnail_url) || bildAdresse(m.media_url);
}
function zeitstempel(t) { const x = Date.parse(String(t || '').replace(/([+-][0-9]{2})([0-9]{2})$/, '$1:$2')); return isNaN(x) ? null : Math.floor(x / 1000); }

function beginnen(st, k) {
  st.tag = String(k.tag || '');
  st.seit_unix = zahl(k.seit_unix) > 0 ? zahl(k.seit_unix) : null;
  st.erster = st.seit_unix === null;
  st.werte = {}; st.konto = {}; st.medien = {}; st.insights = {};
  // Zustand für den Erstabruf nur beim Sofortabruf anlegen; der nächtliche Zustand bleibt unverändert (Stefan 19.10.2026)
  const tageListe = (Array.isArray(k.tage) ? k.tage : []).filter(t => t && /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(t.tag)) && zahl(t.since) > 0 && zahl(t.until) > zahl(t.since))
    .slice(-30).map(t => ({ tag: String(t.tag), since: String(t.since), until: String(t.until) }));
  if (k.erstabruf === true && tageListe.length) { st.erstabruf = true; st.tage = tageListe; st.tw = {}; }
  st.medien_fertig = false; st.seiten = 0;
  // Migration 151 (Punkt 2j): Bildadressen auffrischen = vollständige Liste ohne since; medien_komplett nur, wenn bis zum Ende durchlaufen
  st.auffrischen = k.vorschau_auffrischen === true && !st.erster; st.medien_komplett = false; st.ohne_kinder = false; st.medien_unklar = false;
  st.verfolgt = {};
  for (const b of Array.isArray(k.beitraege) ? k.beitraege : []) {
    if (b && ID_MUSTER.test(String(b.extern_id || ''))) st.verfolgt[String(b.extern_id)] = String(b.produkt_art || b.art || '');
  }
  const ig = st.ig_id;
  const zeiten = st.erstabruf ? st.tage : [{ tag: st.tag, since: String(k.since), until: String(k.until) }];
  for (const z of zeiten) {
    const zeit = { since: z.since, until: z.until };
    const tag = st.erstabruf ? { tag: z.tag } : {};
    st.offen.push(Object.assign({ typ: 'konto_insights', pfad: ig + '/insights', stufe: 'A', query: Object.assign({ metric: KONTO_A, period: 'day', metric_type: 'total_value' }, zeit) }, tag));
    st.offen.push(Object.assign({ typ: 'konto_follows', pfad: ig + '/insights', query: Object.assign({ metric: 'follows_and_unfollows', period: 'day', metric_type: 'total_value', breakdown: 'follow_type' }, zeit) }, tag));
  }
  st.offen.push({ typ: 'konto_felder', pfad: ig, query: { fields: 'followers_count,media_count' } });
  st.offen.push({ typ: 'medien', pfad: ig + '/media', query: Object.assign({ fields: MEDIEN_FELDER, limit: MEDIEN_JE_SEITE }, st.erster || st.auffrischen ? {} : { since: String(st.seit_unix) }) });
  for (const id of Object.keys(st.verfolgt)) st.offen.push(insightsAnfrage(id, st.verfolgt[id], 'voll'));
}

// Kennzahlen des Tages einer Anfrage (Stefan 19.10.2026): Vortag wie bisher in st.werte, beim Erstabruf die übrigen Tage in st.tw
function tagWerte(st, req) {
  const tag = String(req.tag || st.tag);
  if (tag === st.tag) return st.werte;
  st.tw = st.tw || {};
  return (st.tw[tag] = st.tw[tag] || {});
}

function erfolg(st, req, body) {
  const b = body && typeof body === 'object' ? body : {};
  if (req.typ === 'konto_insights') { Object.assign(tagWerte(st, req), kennzahlenAus(b)); return; }
  if (req.typ === 'konto_follows') {
    const tw = tagWerte(st, req);
    for (const m of Array.isArray(b.data) ? b.data : []) {
      if (!m || m.name !== 'follows_and_unfollows') continue;
      const tv = m.total_value || {};
      if (zahl(tv.value) !== null) tw.follows_and_unfollows = zahl(tv.value);
      const auf = {};
      for (const bd of Array.isArray(tv.breakdowns) ? tv.breakdowns : []) {
        for (const r of Array.isArray(bd.results) ? bd.results : []) {
          const key = (Array.isArray(r.dimension_values) ? r.dimension_values : []).join(' / ').slice(0, 80);
          if (key && zahl(r.value) !== null) auf[key] = zahl(r.value);
        }
      }
      if (Object.keys(auf).length) tw.follows_and_unfollows_nach_follow_type = auf;
    }
    return;
  }
  if (req.typ === 'konto_felder') {
    for (const f of ['followers_count', 'media_count']) if (zahl(b[f]) !== null) st.konto[f] = zahl(b[f]);
    return;
  }
  if (req.typ === 'medien') {
    st.seiten++;
    const daten = Array.isArray(b.data) ? b.data : [];
    let aeltester = null;
    for (const m of daten) {
      const e = medium(m);
      if (!e) continue;
      st.medien[e.extern_id] = e;
      const t = zeitstempel(e.erstellt);
      if (t !== null && (aeltester === null || t < aeltester)) aeltester = t;
    }
    const q = b.paging && b.paging.next ? weiterParameter(b.paging.next) : null;
    // Migration 151 (Prüfung 2j, B1): Meta kann eine leere Seite mit next liefern – beim Auffrischen und beim ersten Abruf weiterblättern
    // (bis MAX_SEITEN); eine Antwort ohne Liste data (abgeschnitten) macht die Liste unklar
    if (!Array.isArray(b.data)) st.medien_unklar = true;
    const weiter = q && (daten.length || st.auffrischen || st.erster) && st.seiten < MAX_SEITEN && !(st.seit_unix && !st.auffrischen && aeltester !== null && aeltester < st.seit_unix);
    if (weiter) {
      if (st.seit_unix && !st.auffrischen && !q.since) q.since = String(st.seit_unix);
      q.fields = st.ohne_kinder ? MEDIEN_FELDER_OHNE : MEDIEN_FELDER;
      st.offen.push({ typ: 'medien', pfad: req.pfad, query: q });
      return;
    }
    st.medien_fertig = true;
    // Migration 151: vollständig nur ohne since (Auffrischen oder erster Abruf) und bis zum Ende: kein next mehr (Seitengrenze nicht erreicht)
    // und jede Seite mit Liste data (Prüfung 2j, B1)
    st.medien_komplett = (st.auffrischen || st.erster) && !q && !st.medien_unklar;
    // Neue Beiträge seit dem letzten Abruf gleich mit Zahlen versehen (nicht beim ersten Abruf: dort beendet die Datenbank alte Verfolgungen)
    if (!st.erster) {
      for (const id of Object.keys(st.medien)) {
        const e = st.medien[id];
        if (st.verfolgt[id] !== undefined || String(e.produkt_art || '').toUpperCase() === 'STORY') continue;
        const t = zeitstempel(e.erstellt);
        if (t !== null && t < st.seit_unix) continue;
        st.verfolgt[id] = String(e.produkt_art || e.art || '');
        st.offen.push(insightsAnfrage(id, st.verfolgt[id], 'voll'));
      }
    } else if (st.erstabruf) {
      // Erstabruf (Stefan 19.10.2026): Beiträge der letzten 30 Tage gleich mit Zahlen versehen (neueste zuerst, höchstens 100);
      // ältere bekommen nur like_count/comments_count aus der Liste. Abschließen nach der Verfolgungsdauer macht die Datenbank wie bisher.
      const ab = zahl(st.tage[0].since);
      let anzahl = 0;
      for (const id of Object.keys(st.medien)) {
        const e = st.medien[id];
        if (st.verfolgt[id] !== undefined || String(e.produkt_art || '').toUpperCase() === 'STORY') continue;
        const t = zeitstempel(e.erstellt);
        if (t === null || t < ab || anzahl >= 100) continue;
        anzahl++;
        st.verfolgt[id] = String(e.produkt_art || e.art || '');
        st.offen.push(insightsAnfrage(id, st.verfolgt[id], 'voll'));
      }
    }
    return;
  }
  if (req.typ === 'beitrag_insights') {
    const w = kennzahlenAus(b);
    if (Object.keys(w).length) st.insights[req.extern_id] = Object.assign(st.insights[req.extern_id] || {}, w);
  }
}

// Fehler, die weder Schlüssel, Rechte, Grenze noch vorübergehend sind (meist Code 100): true = weiter, false = Kanal abbrechen
function sonstFehler(st, req, f) {
  if (req.typ === 'konto_insights') {
    if (req.stufe === 'A' && f.code === '100') {
      // Ersatz-Kennzahlen für denselben Tag (Stefan 19.10.2026: beim Erstabruf je Tag)
      st.offen.unshift(Object.assign({ typ: 'konto_insights', pfad: req.pfad, stufe: 'B', query: Object.assign({}, req.query, { metric: KONTO_B }) }, req.tag ? { tag: req.tag } : {}));
      return true;
    }
    st.hinweis = st.hinweis || { code: f.code, text: 'Konto-Kennzahlen nicht abrufbar. ' + f.text };
    return true;
  }
  if (req.typ === 'konto_follows') return true;
  if (req.typ === 'konto_felder') { st.hinweis = st.hinweis || { code: f.code, text: 'Follower-Zahl nicht abrufbar. ' + f.text }; return true; }
  if (req.typ === 'medien') {
    // Migration 151: children nicht angenommen (Fehler 100) → dieselbe Seite ohne children, danach Rückfall media_url (nur Bild)
    if (f.code === '100' && !st.ohne_kinder && String((req.query || {}).fields || '').indexOf('children') >= 0) {
      st.ohne_kinder = true;
      st.offen.unshift({ typ: 'medien', pfad: req.pfad, query: Object.assign({}, req.query, { fields: MEDIEN_FELDER_OHNE }) });
      return true;
    }
    st.medien_fertig = false; st.medien_fehler = true; st.medien_komplett = false;
    st.hinweis = st.hinweis || { code: f.code, text: 'Beitragsliste nicht abrufbar. ' + f.text };
    return true;
  }
  if (req.typ === 'beitrag_insights') {
    if (req.stufe === 'voll' && f.code === '100') { st.offen.unshift(insightsAnfrage(req.extern_id, req.produkt, 'basis')); return true; }
    return true;
  }
  return false;
}

function daten(st) {
  const d = {};
  let hat = false;
  // Konto je Tag (Stefan 19.10.2026): beim Erstabruf alle Tage mit Werten, aufsteigend; sonst wie bisher nur der Vortag
  const tage = Object.keys(st.tw || {}).sort().filter(x => Object.keys(st.tw[x]).length).map(x => ({ tag: x, werte: st.tw[x] }));
  if (Object.keys(st.werte).length) tage.push({ tag: st.tag, werte: st.werte });
  if (tage.length) { d.tage = tage; hat = true; }
  if (Object.keys(st.konto).length) { d.konto = st.konto; if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(st.tag)) d.konto_tag = st.tag; hat = true; }
  const b = {};
  // Beitragsliste nur vollständig speichern (sonst würden ältere Beiträge beim nächsten Abruf übersprungen)
  if (st.medien_fertig) for (const id of Object.keys(st.medien)) {
    b[id] = kopie(st.medien[id]);
    // Migration 151: beim Auffrischen ältere Beiträge nur mit Bildadresse (keine Zahlen, kein Text, kein neuer Beitrag)
    const t = zeitstempel(b[id].erstellt);
    if (st.auffrischen && st.verfolgt[id] === undefined && (t === null || t < st.seit_unix)) {
      const x = b[id];
      b[id] = { extern_id: x.extern_id, art: x.art, produkt_art: x.produkt_art, erstellt: x.erstellt, link: x.link, vorschau_url: x.vorschau_url, nur_vorschau: true };
    }
  }
